INSERT INTO public."Recipe" VALUES (38, '2023-07-30 14:24:05.587949+00', 'Lentil Soup with a Side Salad and Balsamic Dressing', 1, '["Cook the lentils according to the package instructions.","While the lentils are cooking, prepare the side salad by mixing the greens, cherry tomatoes, and cucumber in a bowl.","In a separate small bowl, whisk together the balsamic dressing ingredients.","Once the lentils are cooked, drain any excess liquid and let them cool slightly.","Add the lentils to the side salad and toss with the balsamic dressing.","Serve the lentil soup with the side salad and enjoy!"]');
INSERT INTO public."Recipe" VALUES (39, '2023-07-30 14:27:02.56245+00', 'Quinoa and black bean salad with diced tomatoes corn, red onion and lime dressing', 2, '["Cook quinoa according to package instructions and let it cool.","In a large bowl, combine cooked quinoa, black beans, diced tomatoes, corn, and red onion.","In a small bowl, whisk together lime juice, olive oil, salt, and pepper to make the dressing.","Pour the dressing over the quinoa mixture and toss to combine.","Serve chilled and enjoy!"]');
INSERT INTO public."Recipe" VALUES (40, '2023-07-30 14:29:02.829591+00', 'Quinoa-stuffed bell peppers with onions and mushrooms', 1, '["Preheat the oven to 180°C.","Cut the tops off the bell peppers and remove the seeds and membranes.","In a large skillet, heat olive oil over medium heat.","Add onions and mushrooms and cook until softened, about 5 minutes.","Add garlic and cook for an additional minute.","In a medium bowl, combine cooked quinoa, sautéed onions and mushrooms, black beans, corn, and spices.","Stuff the bell peppers with the quinoa mixture.","Place the stuffed bell peppers in a baking dish and cover with foil.","Bake for 25-30 minutes, or until the peppers are tender.","Remove from the oven and let cool for a few minutes before serving."]');
INSERT INTO public."Recipe" VALUES (41, '2023-07-30 14:31:37.664542+00', 'Turkey lettuce wraps with lean ground turkey, lettuce leaves, bell peppers and a drizzle of low-sodium soy sauce', 4, '["Heat a non-stick pan over medium heat.","Add the lean ground turkey and cook until browned.","Wash and separate the lettuce leaves.","Slice the bell peppers into thin strips.","In a small bowl, mix the low-sodium soy sauce with a pinch of black pepper.","Place a lettuce leaf on a plate and add a spoonful of the cooked ground turkey.","Top with bell pepper strips and drizzle with the soy sauce mixture.","Repeat with the remaining lettuce leaves and ingredients.","Serve immediately and enjoy!"]');
INSERT INTO public."Recipe" VALUES (43, '2023-07-30 14:35:57.333133+00', 'Baked Chicken Breast with Steamed Broccoli and Quinoa', 2, '["Preheat the oven to 200°C.","Season the chicken breasts with salt, pepper, and any other desired spices.","Place the chicken breasts on a baking sheet lined with parchment paper.","Bake the chicken breasts in the preheated oven for 20-25 minutes or until cooked through.","While the chicken is baking, prepare the quinoa according to the package instructions.","Steam the broccoli until tender.","Once the chicken is cooked, remove it from the oven and let it rest for a few minutes before slicing.","Serve the sliced chicken breast with steamed broccoli and cooked quinoa."]');
INSERT INTO public."Recipe" VALUES (44, '2023-07-30 14:38:57.873772+00', 'Baked Turkey Meatballs with Zucchini Pancakes', 2, '["Preheat the oven to 180°C.","In a large bowl, combine ground turkey, breadcrumbs, grated onion, minced garlic, egg, salt, and pepper. Mix well.","Shape the mixture into meatballs and place them on a baking sheet lined with parchment paper.","Bake the meatballs in the preheated oven for 20-25 minutes, or until cooked through.","Meanwhile, prepare the zucchini pancakes. Grate the zucchini and squeeze out any excess moisture.","In a separate bowl, whisk together flour, baking powder, salt, and pepper. Add the grated zucchini and mix well.","Heat a non-stick skillet over medium heat and add a small amount of oil. Drop spoonfuls of the zucchini batter onto the skillet and cook until golden brown on both sides.","Serve the baked turkey meatballs with the zucchini pancakes and enjoy!"]');
INSERT INTO public."Recipe" VALUES (27, '2023-07-30 10:25:26.327791+00', 'Apple slices with peanut butter', 2, '[]');
INSERT INTO public."Recipe" VALUES (28, '2023-07-30 10:26:28.536056+00', 'Dark chocolate squares', 2, '[]');
INSERT INTO public."Recipe" VALUES (29, '2023-07-30 10:27:56.228525+00', 'Fresh berries', 2, '[]');
INSERT INTO public."Recipe" VALUES (30, '2023-07-30 10:29:25.441598+00', 'Fruit salad', 2, '[]');
INSERT INTO public."Recipe" VALUES (31, '2023-07-30 10:29:57.960364+00', 'Frozen grapes', 2, '[]');
INSERT INTO public."Recipe" VALUES (32, '2023-07-30 10:30:50.982137+00', 'Greek yogurth with a drizzle of honey', 2, '[]');
INSERT INTO public."Recipe" VALUES (33, '2023-07-30 10:34:40.681028+00', 'Chickpea salad with diced cucumbers, cherry tomatoes, red onion and lemon dressing', 2, '[]');
INSERT INTO public."Recipe" VALUES (35, '2023-07-30 14:10:26.340157+00', 'Chicken Stir-Fry', 2, '["Heat oil in a large skillet over medium-high heat.","Add chicken and cook until browned.","Remove chicken from skillet and set aside.","In the same skillet, add onion, bell pepper, and broccoli.","Cook until vegetables are tender-crisp.","Add garlic and ginger, cook for 1 minute.","Return chicken to skillet and add soy sauce and honey.","Cook for an additional 2 minutes, stirring occasionally.","Serve hot over rice or noodles."]');
INSERT INTO public."Recipe" VALUES (36, '2023-07-30 14:15:53.849406+00', 'Grilled Chicken Breast Salad with Mixed Greens, Cherry Tomatoes, Cucumber and Vinaigrette Dressing', 2, '["Grill the chicken breast until cooked through.","Slice the chicken breast into thin strips.","Wash and dry the mixed greens, cherry tomatoes, and cucumber.","Slice the cherry tomatoes in half.","Slice the cucumber into thin rounds.","Prepare the vinaigrette dressing by combining olive oil, vinegar, mustard, salt, and pepper in a small bowl.","Toss the mixed greens, cherry tomatoes, and cucumber with the vinaigrette dressing.","Top the salad with the grilled chicken breast strips.","Serve and enjoy!"]');
INSERT INTO public."Recipe" VALUES (55, '2023-07-30 15:12:43.65136+00', 'Spinach and feta cheese omelet with a side of black beans', 2, '["Heat a non-stick pan over medium heat.","Add 1 teaspoon of olive oil to the pan.","Add 100 grams of spinach to the pan and cook until wilted.","In a bowl, whisk together 4 eggs, 50 grams of feta cheese (crumbled), and a pinch of salt and pepper.","Pour the egg mixture into the pan with the spinach.","Cook the omelet for 2-3 minutes, or until the edges are set.","Flip the omelet and cook for an additional 2-3 minutes, or until cooked through."]');
INSERT INTO public."Recipe" VALUES (54, '2023-07-30 15:01:22.68731+00', 'Sliced Cucumbers with Tzatziki Sauce', 2, '["Slice the cucumbers into thin rounds.","Prepare the tzatziki sauce by combining Greek yogurt, grated cucumber, minced garlic, lemon juice, and chopped dill in a bowl.","Season the tzatziki sauce with salt and pepper to taste.","Serve the sliced cucumbers with the tzatziki sauce on the side."]');
INSERT INTO public."Recipe" VALUES (53, '2023-07-30 14:59:30.831701+00', 'Sliced Bell Peppers with Guacamole', 2, '["Slice the bell peppers into thin strips.","Prepare the guacamole by mashing the avocados and mixing them with lime juice, diced tomatoes, minced garlic, and salt.","Serve the sliced bell peppers with the guacamole on the side."]');
INSERT INTO public."Recipe" VALUES (52, '2023-07-30 14:58:05.539861+00', 'Greek yogurth with a handful of mixed nuts', 2, '[]');
INSERT INTO public."Recipe" VALUES (51, '2023-07-30 14:56:55.925818+00', 'Cottage cheese with pineapple', 2, '[]');
INSERT INTO public."Recipe" VALUES (50, '2023-07-30 14:56:05.452133+00', 'Cherry tomatoes with mozarella cheese', 2, '[]');
INSERT INTO public."Recipe" VALUES (26, '2023-07-29 08:24:06.883278+00', 'Avocado and grilled chicken on whole grain toast', 2, '[]');
INSERT INTO public."Recipe" VALUES (37, '2023-07-30 14:21:08.879136+00', 'Grilled tofu wrap with a whole wheat tortilla, mixed greens, and light dressing', 4, '["Preheat the grill to medium-high heat.","Slice the tofu into thin strips.","In a small bowl, mix together the soy sauce, garlic powder, and black pepper.","Brush the tofu strips with the soy sauce mixture.","Grill the tofu for 2-3 minutes on each side, or until lightly charred.","Warm the whole wheat tortillas on the grill for about 30 seconds on each side.","Spread a thin layer of light dressing on each tortilla.","Place a handful of mixed greens on each tortilla.","Top with the grilled tofu strips.","Roll up the tortillas tightly, tucking in the sides as you go.","Slice the wraps in half and serve."]');
INSERT INTO public."Recipe" VALUES (56, '2023-08-12 11:37:53.781+00', 'Protein-packed Lentil Salad', 4, '["Cook the lentils according to package instructions.","In a large bowl, combine the cooked lentils, chopped vegetables, and herbs.","In a small bowl, whisk together the olive oil, lemon juice, salt, and pepper to make the dressing.","Pour the dressing over the lentil mixture and toss to combine.","Serve the salad chilled or at room temperature."]');
INSERT INTO public."Recipe" VALUES (42, '2023-07-30 14:34:27.782688+00', 'Baked Chicken Breast with Roasted Brussel Sprouts and Cauliflower Rice', 2, '["Preheat the oven to 200°C.","Season the chicken breasts with salt, pepper, and any other desired spices.","Place the chicken breasts on a baking sheet lined with parchment paper.","Bake in the preheated oven for 20-25 minutes or until the chicken is cooked through.","While the chicken is baking, prepare the roasted brussel sprouts and cauliflower rice.","Trim the ends of the brussel sprouts and cut them in half.","Toss the brussel sprouts with olive oil, salt, and pepper.","Spread the brussel sprouts on a separate baking sheet.","Roast in the oven for 15-20 minutes or until the brussel sprouts are tender and slightly browned.","For the cauliflower rice, cut the cauliflower into florets and pulse in a food processor until it resembles rice grains.","Heat a tablespoon of olive oil in a large skillet over medium heat.","Add the cauliflower rice to the skillet and cook for 5-7 minutes or until tender.","Season with salt and pepper to taste.","Serve the baked chicken breast with the roasted brussel sprouts and cauliflower rice."]');
INSERT INTO public."Recipe" VALUES (49, '2023-07-30 14:53:49.494243+00', 'Carrot Sticks with Hummus', 2, '["Peel and cut the carrots into sticks.","Prepare the hummus by blending chickpeas, tahini, lemon juice, garlic, and olive oil until smooth.","Serve the carrot sticks with the hummus dip."]');
INSERT INTO public."Recipe" VALUES (48, '2023-07-30 14:50:20.681443+00', 'Rice Cakes with Almond Butter', 2, '["Cook the rice cakes according to the package instructions.","Spread almond butter on top of each rice cake.","Serve and enjoy!"]');
INSERT INTO public."Recipe" VALUES (47, '2023-07-30 14:48:15.370238+00', 'Lentil Curry with Cauliflower Rice', 4, '["Heat oil in a large pot over medium heat.","Add onion, garlic, and ginger. Cook until onion is translucent.","Add curry powder, cumin, and turmeric. Cook for 1 minute.","Add lentils, vegetable broth, and coconut milk. Bring to a boil.","Reduce heat and simmer for 20 minutes, or until lentils are tender.","Meanwhile, prepare the cauliflower rice. Grate cauliflower using a box grater or food processor.","Heat oil in a large skillet over medium heat.","Add cauliflower rice and cook for 5 minutes, or until tender.","Season with salt and pepper to taste.","Serve the lentil curry over the cauliflower rice. Enjoy!"]');
INSERT INTO public."Recipe" VALUES (46, '2023-07-30 14:44:00.42329+00', 'Grilled Tofu with Stir-Fried Vegetables', 2, '["Prepare the tofu by pressing it to remove excess moisture.","Marinate the tofu in a mixture of soy sauce, garlic, and ginger for at least 30 minutes.","Heat a grill pan or grill over medium-high heat.","Grill the tofu for 4-5 minutes on each side, or until grill marks appear.","While the tofu is grilling, prepare the stir-fried vegetables.","Heat a large skillet or wok over medium-high heat.","Add a tablespoon of oil and swirl to coat the pan.","Add the vegetables and stir-fry for 3-4 minutes, or until crisp-tender.","In a small bowl, whisk together soy sauce, sesame oil, and cornstarch.","Pour the sauce over the vegetables and cook for an additional 1-2 minutes, or until the sauce has thickened.","Serve the grilled tofu with the stir-fried vegetables."]');
INSERT INTO public."Recipe" VALUES (45, '2023-07-30 14:40:52.19099+00', 'Grilled Chicken Breast with Steamed Asparagus and Sweet Potato Wedges', 2, '["Preheat the grill to medium-high heat.","Season the chicken breasts with salt and pepper.","Grill the chicken breasts for about 6-8 minutes per side, or until cooked through.","While the chicken is grilling, prepare the asparagus and sweet potato wedges.","Steam the asparagus for about 5 minutes, or until tender-crisp.","Cut the sweet potatoes into wedges and toss with olive oil, salt, and pepper.","Bake the sweet potato wedges in a preheated oven at 200°C for about 20-25 minutes, or until crispy and golden brown.","Serve the grilled chicken breasts with steamed asparagus and sweet potato wedges."]');
INSERT INTO public."Recipe" VALUES (57, '2023-08-28 06:16:10.629+00', 'Scrambled eggs with tomato and bread', 1, '[]');
