INSERT INTO public."Recipe" VALUES (60, '2023-08-28 06:21:53.066+00', 'Fruit shake', 1, '[]');
INSERT INTO public."Recipe" VALUES (61, '2023-08-28 06:25:22.02+00', 'Poultry rolls with baked potatoes and salad', 2, '[" Umyć, pokroić i rozbić mięso tłuczkiem, przyprawić ulubionymi przyprawami","Ogórki oraz ser pokroić w paski, następnie ułozyć na przygotowanych porcjach mięsa i zawinąć","Piec w piekarniku w temperaturze 180 stopni przez 20 minut, razem z pokrojonymi drobno ziemniakami - zarówno ziemniaki, jak i mięso polewamy oliwą przed obróbką termiczną. Innym rozwiązaniem jest ugotowanie ziemniaków i usmażenie roladek na patelni.","Całość podać z pomidrem i sałatą, wymieszanymi z jogurtem "]');
INSERT INTO public."Recipe" VALUES (62, '2023-08-28 06:29:46.797+00', 'Buckweat with meat in sauce and salad', 2, '["Kasze ugotować zgodnie z przepisem na opakowaniu","Pokrojone mięso podsmażyc na oliwie razem z cebulą"," Po kilku minutach dodać koncentrat pomidorowy, poddusić, doprawić","Całość podać z surówką z ogórków kiszonych, papryki i sałaty"]');
INSERT INTO public."Recipe" VALUES (63, '2023-08-28 06:33:13.132+00', 'Burgers', 2, '["Bułkę przekroić (można podpiec), posmarować ketchupem i ułożyć warzywa"," Do bułki włożyć usmażonego na oliwie kotleta z chudego mięsa (dostępne w biedronce)","Burgery podawać z pokrojoną w paski papryką","Sugerowane przyprawy: pieprz, sól, kurkuma, oregano"]');
